 static object Resources(){var list=new List<Process>();using(var q=new ManagementObjectSearcher("SELECT ProcessId,ExecutablePath FROM Win32_Process"))foreach(ManagementObject row in q.Get()){string p=Convert.ToString(row["ExecutablePath"]);if(p!=""&&HostCore.Within(p,install))list.Add(Process.GetProcessById(Convert.ToInt32(row["ProcessId"])));}var before=list.ToDictionary(p=>p.Id,p=>p.TotalProcessorTime.TotalSeconds);Thread.Sleep(15000);var metrics=new List<object>();double cpu=0;foreach(var p in list){try{p.Refresh();double seconds=p.TotalProcessorTime.TotalSeconds-before[p.Id];cpu+=seconds;metrics.Add(new{pid=p.Id,name=p.ProcessName,workingSetBytes=p.WorkingSet64,privateBytes=p.PrivateMemorySize64,cpuSecondsOver15s=seconds});}finally{p.Dispose();}}return new{mode="local-only advanced HTTP gateway (not the unverified Secure Tunnel chain)",seconds=15,cpuPercentOfOneCore=cpu/15*100,cpuPercentOfMachine=cpu/15/Environment.ProcessorCount*100,processes=metrics};}
