  root=HostCore.Full(args[1]);if(root.IndexOf(".ygpt-local-tests",StringComparison.OrdinalIgnoreCase)<0||Directory.Exists(root))throw new Exception("New named disposable root required");Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(root,"helper-temp"));data=Path.Combine(root,"data");install=Path.Combine(root,"application");string workspace=Path.Combine(root,"workspace");Directory.CreateDirectory(workspace);File.WriteAllText(Path.Combine(workspace,"sentinel.txt"),"KEEP_USER_FILE");string download=Path.Combine(root,"installer-download.exe");File.Copy(args[0],download);gui=Launch(download,"--install-dir "+HostCore.Q(install)+" --data-dir "+HostCore.Q(data));Window();
  Value("folder",workspace);Page("01-welcome");Invoke("next");Check(Find("setup-message").Current.Name.Contains("Confirm local access"),"First-run consent blocks installation");Toggle("consent");Invoke("next");Page("02-environment");Check(((TogglePattern)Find("auto-start").GetCurrentPattern(TogglePattern.Pattern)).Current.ToggleState==ToggleState.On,"Login task enabled by default");Invoke("next");Page("03-connection");Expand("advanced-connections");((SelectionItemPattern)Find("mode-local-only").GetCurrentPattern(SelectionItemPattern.Pattern)).Select();Invoke("next");Page("04-credentials");Invoke("next");Page("05-install");Invoke("next");phase="installing";
