  phase="duplicate-start";using(var duplicate=Launch(Path.Combine(install,"YGPTWatchdog.exe"),"--data-dir "+HostCore.Q(data))){Check(duplicate.WaitForExit(10000)&&duplicate.ExitCode==0,"Duplicate Watchdog exits without a second owner");}Check(Convert.ToInt32(Health()["pid"])==pid,"Duplicate launch retains the original owner");
  dynamic scheduler=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));scheduler.Connect();dynamic task=scheduler.GetFolder("\\").GetTask(HostCore.TaskName(data));Check(Convert.ToString(task.Definition.Actions.Item(1).Path)==Path.Combine(install,"YGPTWatchdog.exe"),"Login action points to standalone Watchdog");task.Run(null);Thread.Sleep(2000);Check(Convert.ToInt32(Health()["pid"])==pid,"Task action and manual start share one owner");
