 }catch(Exception e){report["error"]=e.Message;report["errorType"]=e.GetType().Name;}finally{report["phase"]=phase;report["checks"]=checks;report["at"]=DateTime.UtcNow.ToString("o");if(root!=null&&Directory.Exists(root))HostCore.Save(Path.Combine(root,"native-install-result.json"),report);if(args.Length>2)HostCore.Save(args[2],report);if(gui!=null&&!gui.HasExited)gui.CloseMainWindow();if(data!=null&&Directory.Exists(data)){try{HostCore.Pause(data);}catch{}try{HostCore.RegisterTask(install,data,false);}catch{}}Console.WriteLine(HostCore.Json.Serialize(report));}return HostCore.B(report,"passed")?0:1;}
